for row in GameInfo.District_Adjacencies() do
	if(row.DistrictType == districtType) then
		has_bonus[row.YieldChangeId] = true;
	end
end

for row in GameInfo.Adjacency_YieldChanges() do
	if(has_bonus[row.ID]) then

		local object;
		if(row.OtherDistrictAdjacent) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_DISTRICT";
		elseif(row.AdjacentResource) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_RESOURCE";
		elseif(row.AdjacentSeaResource) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_SEA_RESOURCE";
		elseif(row.AdjacentResourceClass ~= "NO_RESOURCECLASS") then
			if(row.AdjacentResourceClass == "RESOURCECLASS_BONUS") then
				object = "LOC_TOOLTIP_BONUS_RESOURCE";
			elseif(row.AdjacentResourceClass == "RESOURCECLASS_LUXURY") then
				object = "LOC_TOOLTIP_LUXURY_RESOURCE";
			elseif(row.AdjacentResourceClass == "RESOURCECLASS_STRATEGIC") then
				object = "LOC_TOOLTIP_BONUS_STRATEGIC";
			elseif(row.AdjacentResourceClass == "RESOURCECLASS_LEY_LINE") then
				object = "LOC_TOOLTIP_LEY_LINE_RESOURCE";
			else
				object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_RESOURCE_CLASS";
			end
		elseif(row.AdjacentRiver) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_RIVER";
		elseif(row.AdjacentWonder) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_WONDER";
		elseif(row.AdjacentNaturalWonder) then
			object = "LOC_TYPE_TRAIT_ADJACENT_OBJECT_NATURAL_WONDER";
		elseif(row.AdjacentTerrain) then
			local terrain = GameInfo.Terrains[row.AdjacentTerrain];
			if(terrain) then
				object = terrain.Name;
			end
		elseif(row.AdjacentFeature) then
			local feature = GameInfo.Features[row.AdjacentFeature];
			if(feature) then
				object = feature.Name;
			end
		elseif(row.AdjacentImprovement) then
			local improvement = GameInfo.Improvements[row.AdjacentImprovement];
			if(improvement) then
				object = improvement.Name;
			end
		elseif(row.AdjacentDistrict) then		
			local district = GameInfo.Districts[row.AdjacentDistrict];
			if(district) then
				object = district.Name;
			end
		end

		local yield = GameInfo.Yields[row.YieldType];

		if(object and yield) then

			local key = (row.TilesRequired > 1) and "LOC_TYPE_TRAIT_ADJACENT_BONUS_PER" or "LOC_TYPE_TRAIT_ADJACENT_BONUS";

			-- Exception - Adjacent river gold bonuses can only be gained once
			if row.AdjacentRiver == true then
				key = "LOC_TYPE_TRAIT_ADJACENT_BONUS_ONCE";
			end

			local value = Locale.Lookup(key, row.YieldChange, yield.IconString, yield.Name, row.TilesRequired, object);

			if(row.PrereqCivic or row.PrereqTech) then
				local item;
				if(row.PrereqCivic) then
					item = GameInfo.Civics[row.PrereqCivic];

end
instance.DownCost:SetText(cost == 0 and " " or Locale.Lookup("LOC_WORLD_CONGRESS_FAVOR", cost * (kVoteData.voteDirection > 0 and -1 or 1)));
instance.DownButton:SetToolTipString(tooltip);

if kVoteData.voteBlocker then
	if kVoteData.voteBlocker.NoUpvote and kVoteData.voteBlocker.NoDownvote then
		instance.UpButton:SetDisabled(true);
		instance.DownButton:SetDisabled(true);
		instance.UpButton:SetToolTipString(Locale.Lookup(kVoteData.voteBlocker.Description));
		instance.DownButton:SetToolTipString(Locale.Lookup(kVoteData.voteBlocker.Description));
	elseif kVoteData.voteBlocker.NoUpvote and kVoteData.votes == 0 then
		instance.UpButton:SetDisabled(true);
		instance.UpButton:SetToolTipString(Locale.Lookup(kVoteData.voteBlocker.Description));
	elseif kVoteData.voteBlocker.NoDownvote and kVoteData.votes == 0 then
		instance.DownButton:SetDisabled(true);
		instance.DownButton:SetToolTipString(Locale.Lookup(kVoteData.voteBlocker.Description));
	end
end

if kVoteData.votes == 0 then
	if not kVoteData.voteBlocker or not kVoteData.voteBlocker.NoUpvote then
		instance.UpButton:SetToolTipString(Locale.Lookup(resolutionChoice and "LOC_WORLD_CONGRESS_TT_NO_VOTING_DOWN" or "LOC_WORLD_CONGRESS_TT_PLEASE_VOTE_FOR"));
	end
	if not kVoteData.voteBlocker or not kVoteData.voteBlocker.NoDownvote then
		local bIsTarget:boolean = kVoteData.data.Target == Game.GetLocalPlayer();
		if bIsTarget then
			instance.DownButton:SetToolTipString(Locale.Lookup("LOC_WORLD_CONGRESS_TT_PLEASE_VOTE_AGAINST_TARGET"));
		else
			instance.DownButton:SetToolTipString(Locale.Lookup(resolutionChoice and "" or "LOC_WORLD_CONGRESS_TT_PLEASE_VOTE_AGAINST"));

for _, kProposal in pairs(kProposals) do
	-- Create proposal vote data
	local voteKey:string = GetProposalVoteKey(kProposal);
	local kVoteData:table = m_kProposalVotes[voteKey];
	if not kVoteData then
		kVoteData = {
			cost = 0,
			votes = kProposal.Disabled and 1 or DEBUG_DATA and 1 or 0,
			data = kProposal,
			voteDirection = NO_VOTE,
			disabled = kProposal.Disabled and true or false,
			voteBlocker = kProposal.VotingRestriction and GameInfo.VotingBlockers[kProposal.VotingRestriction] or nil,
			proposalBlocker = kProposal.ProposalBlockerType and GameInfo.ProposalBlockers[kProposal.ProposalBlockerType] or nil
		};
	end

	local canVote:boolean = not kVoteData.disabled and not (kVoteData.voteBlocker and kVoteData.voteBlocker.NoUpvote and kVoteData.voteBlocker.NoDownvote);
	if canVote or (not m_IsInSession and m_ReviewTab == REVIEW_TAB_AVAILABLE_PROPOSALS) then
		numAllocated = numAllocated + 1;
		local instance:table = kProposalIM:GetInstance();

		-- Only store vote data for proposals players can vote on
		kVoteData.instance = instance;
		m_kProposalVotes[voteKey] = kVoteData;

		-- This allows us to update the total cost 
		instance.UpdateTitle = updateTitleFn;

-- ===========================================================================
local m_currStageNum:number = -1;

-- ===========================================================================
--	OnClose: Closes the popup
-- ===========================================================================
function OnClose()
	UIManager:DequeuePopup(ContextPtr);
	LuaEvents.WorldCongressIntro_ShowWorldCongress();
end

-- ===========================================================================
--	OnOpen: Opens the popup 
-- ===========================================================================
function OnOpen(stageNum:number)
	local pPlayer = PlayerConfigurations[Game.GetLocalPlayer()];
		if(pPlayer ~= nil and pPlayer:IsAlive())then
		UI.PlaySound("WC_Open");
		Controls.Title:LocalizeAndSetText(stageNum == 1 and "LOC_WORLD_CONGRESS_INTRO_TITLE" or "LOC_SPECIAL_CONGRESS_INTRO_TITLE");
		Controls.Body1:LocalizeAndSetText(stageNum == 1 and "LOC_WORLD_CONGRESS_INTRO_BODY_1" or "LOC_SPECIAL_CONGRESS_INTRO_BODY_1");
		Controls.Body2:LocalizeAndSetText(stageNum == 1 and "LOC_WORLD_CONGRESS_INTRO_BODY_2" or "LOC_SPECIAL_CONGRESS_INTRO_BODY_2");

	--Stop Listening
	LuaEvents.GameDebug_Return.Remove(OnGameDebugReturn);

	--Setup reload variables
	LuaEvents.GameDebug_AddValue(RELOAD_CACHE_ID, "IsHidden", ContextPtr:IsHidden());
	LuaEvents.GameDebug_AddValue(RELOAD_CACHE_ID, "m_currStageNum", m_currStageNum);
end

-- ===========================================================================
-- Consume all input except Continue keys
-- ===========================================================================
function OnInputActionTriggered( actionId:number )
    if ContextPtr:IsHidden() then
       return;
    end

    if actionId == Input.GetActionId("EndTurn") then
		OnClose();
	end
end

-- ===========================================================================
function OnInputHandler( pInputStruct:table )
    if ContextPtr:IsHidden() then
       return false;
    end

	local uiMsg = pInputStruct:GetMessageType();
	local key = pInputStruct:GetKey();
	if uiMsg == KeyEvents.KeyUp and (key == Keys.VK_ESCAPE or key == Keys.VK_RETURN) then
		OnClose();
	end
	return true;
end

-- ===========================================================================
-- Update Turn Timers
-- ===========================================================================
function OnTurnTimerUpdated(elapsedTime :number, maxTurnTime :number)
	if ContextPtr:IsHidden() then return; end
	if maxTurnTime <= 0 then
		Controls.AcceptButton:SetText(Locale.Lookup("LOC_WORLD_CONGRESS_INTRO_ACCEPT"));
	else
		local timeLeft:number = SoftRound(maxTurnTime - elapsedTime);
		Controls.AcceptButton:SetText(Locale.Lookup("LOC_WORLD_CONGRESS_INTRO_ACCEPT") .. " (" .. FormatTimeRemaining(timeLeft, true) .. ")");
	end
end

-- ===========================================================================
--	The load screen has closed.  Check to see if we have to restore our state
-- ===========================================================================
function OnLoadScreenClose()
	local turnSegment = Game.GetCurrentTurnSegment();
	if turnSegment == WORLD_CONGRESS_STAGE_1 then
		OnOpen(1);
	elseif turnSegment == WORLD_CONGRESS_STAGE_2 then
		OnOpen(2);
	end
end

-- ===========================================================================
--	Initialize
-- ===========================================================================
function Initialize()
	ContextPtr:SetHide(true); -- PRODUCTION
	ContextPtr:SetInitHandler(OnInit);
	ContextPtr:SetShutdown(OnShutdown);
	ContextPtr:SetInputHandler(OnInputHandler, true);

	LuaEvents.GameDebug_Return.Add(OnGameDebugReturn);
